    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        try {
            ranges.add(new TimeRange(current, next));
        } catch (Exception e) {
            // If TimeRange constructor throws, wrap and rethrow as runtime to avoid silent failure
            throw new RuntimeException("Failed to create TimeRange from " + current + " to " + next, e);
