protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> ranges = new ArrayList<>();
        if (end < start) {
            throw new IllegalArgumentException("end must be >= start");
        }
        // If FETCH_DATA_DURATION is zero or negative treat the whole range as one chunk
        long maxDuration = FETCH_DATA_DURATION;
        if (maxDuration <= 0) {
            ranges.add(new TimeRange(start, end));
            return ranges;
        }
        long currentStart = start;
        while (currentStart <= end) {
            // Avoid overflow when computing the end of the chunk
            long chunkEnd;
            if (currentStart > Long.MAX_VALUE - maxDuration + 1) {
                chunkEnd = end;
            } else {
                chunkEnd = Math.min(currentStart + maxDuration - 1, end);
            }
            ranges.add(new TimeRange(currentStart, chunkEnd));
            currentStart = chunkEnd + 1;
        }
