public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Timestamp
        String timestamp = "";
        try {
            java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
            timestamp = sdf.format(new java.util.Date(event.getTimeStamp()));
        } catch (Throwable t) {
            timestamp = Long.toString(event.getTimeStamp());
        }

        // Level
        String level = (event.getLevel() != null) ? event.getLevel().toString() : "UNKNOWN";

        // Logger name
        String loggerName = (event.getLoggerName() != null) ? event.getLoggerName() : "";

        // Message
        String message = (event.getRenderedMessage() != null) ? event.getRenderedMessage() : "";

        StringBuilder sb = new StringBuilder();
        sb.append('[').append(timestamp).append("] ")
          .append('[').append(level).append("] ")
          .append('[').append(loggerName).append("] ")
          .append(message);

        // Exception stack trace if present
        if (event.getThrowableInformation() != null) {
            Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                java.io.StringWriter sw = new java.io.StringWriter();
                java.io.PrintWriter pw = new java.io.PrintWriter(sw);
                t.printStackTrace(pw);
                pw.flush();
                sb.append(System.lineSeparator()).append(sw.toString());
            }
        }

        return sb.toString();
    } catch (Throwable e) {
        // In case of any unexpected error, return simple representation
        return String.valueOf(event);
    }
