@Override public String readString() throws IOException {
    // Read length prefix; negative length indicates null string
    int length;
    try {
        length = in.readInt();
    } catch (Exception e) {
        throw new IOException("Failed to read string length", e);
    }
    if (length < 0) {
        // Convention: -1 represents null
        if (length == -1) {
            return null;
        }
        throw new IOException("Invalid string length: " + length);
    }
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        offset += read;
    }
    try {
        return new String(bytes, "UTF-8");
    } catch (Exception e) {
        throw new IOException("Unsupported encoding", e);
