   then read that many bytes and convert to a UTF‑8 string. */
    int b1 = in.read();
    int b2 = in.read();
    int b3 = in.read();
    int b4 = in.read();
    if (b1 == -1 || b2 == -1 || b3 == -1 || b4 == -1) {
        throw new EOFException("Unexpected end of stream while reading string length");
    }
    int length = ((b1 & 0xFF) << 24) | ((b2 & 0xFF) << 16) | ((b3 & 0xFF) << 8) | (b4 & 0xFF);
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        offset += read;
    }
    return new String(bytes, "UTF-8");
