byte[] toByteArray() {
    if (buffer == null) {
        return new byte[0];
    }
    int pos = buffer.position();
    int limit = buffer.limit();
    int remaining = limit - pos;
    if (remaining <= 0) {
        return new byte[0];
    }
    byte[] result = new byte[remaining];
    if (buffer.hasArray()) {
        int offset = buffer.arrayOffset() + pos;
        System.arraycopy(buffer.array(), offset, result, 0, remaining);
    } else {
        buffer.mark();
        buffer.get(result);
        buffer.reset();
    }
    buffer.position(pos);
    return result;
}<|return|>

