private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    java.util.List<Integer> suffixSums = new java.util.ArrayList<>(n);
    long totalSum = 0L;
    try {
        // Compute total sum
        for (int value : bounds) {
            totalSum += value;
        }
        // Compute suffix sums from end to start
        long running = 0L;
        for (int i = n - 1; i >= 0; i--) {
            running += bounds.get(i);
            // Store as int, truncating if overflow
            suffixSums.add(0, (int) running);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute suffix sum", e);
    }
    return new Pair<>(suffixSums, totalSum);
