    // and public references to them. If the underlying implementation
    // differs, this code will need to be adapted accordingly.
    ListNodeImpl<E> curr = list.head;
    ListNodeImpl<E> tail = list.tail;
    while (curr != null && curr != tail) {
        ListNodeImpl<E> next = curr.next;
