private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        // A null or single-vertex set is trivially a clique.
        return true;
    }
    // Convert to a list for indexed access if desired, but nested loops with sets works as well.
    for (V v1 : vertices) {
        if (v1 == null) {
            return false;
        }
        for (V v2 : vertices) {
            if (v1.equals(v2) || v2 == null) {
                continue;
            }
            // For directed graphs, an edge may be present in either direction.
            E e1 = graph.getEdge(v1, v2);
            E e2 = graph.getEdge(v2, v1);
            if (e1 == null && e2 == null) {
                return false;
            }
        }
    }
